package com.vnshop.invoiceservice.infrastructure.web; import com.vnshop.invoiceservice.infrastructure.dlt.DurableDltService; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/admin/dlt") public class AdminDltController { private final DurableDltService service; private final KafkaTemplate<String,Object> kafka; public AdminDltController(DurableDltService s,KafkaTemplate<String,Object> k){service=s;kafka=k;} @PostMapping("/{id}/replay") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> replay(@PathVariable UUID id){service.replay(id,kafka);return ResponseEntity.accepted().build();} }
